Looking at this problem, I need to recover plaintext from a stream cipher reuse attack. When the same keystream is XORed with multiple messages, I can exploit the known plaintexts to recover the keystream and decrypt the target.

Key observations:
1. All ciphertexts use the same keystream (stream cipher with nonce reuse)
2. I have known plaintexts at various positions for different messages
3. For each position where I know plaintext, I can recover that keystream byte: `keystream[i] = ciphertext[i] XOR plaintext[i]`
4. Once I have keystream bytes, I can decrypt the target: `plaintext[i] = ciphertext[i] XOR keystream[i]`

```python
import sys
import json

def hex_to_bytes(hex_str):
    return bytes.fromhex(hex_str)

def bytes_to_hex(b):
    return b.hex()

def main():
    with open(sys.argv[1], 'r') as f:
        instance = json.load(f)

    target = instance['target']
    ciphertexts = instance['ciphertexts']
    known_plaintexts = instance['known_plaintexts']

    # Convert ciphertexts to bytes
    ciphertext_data = {}
    for ct in ciphertexts:
        ciphertext_data[ct['message_index']] = hex_to_bytes(ct['data'])

    # Recover keystream bytes from known plaintexts
    keystream = {}
    for kp in known_plaintexts:
        msg_idx = kp['message_index']
        offset = kp['offset']
        plaintext_bytes = hex_to_bytes(kp['data'])

        ciphertext = ciphertext_data[msg_idx]

        for i, pt_byte in enumerate(plaintext_bytes):
            pos = offset + i
            if pos < len(ciphertext):
                keystream[pos] = ciphertext[pos] ^ pt_byte

    # Decrypt target message
    target_msg_idx = target['message_index']
    target_offset = target['offset']
    target_length = target['length']

    target_ciphertext = ciphertext_data[target_msg_idx]

    plaintext_bytes = bytearray(target_length)
    for i in range(target_length):
        pos = target_offset + i
        if pos in keystream and pos < len(target_ciphertext):
            plaintext_bytes[i] = target_ciphertext[pos] ^ keystream[pos]
        else:
            # Should not happen if we have enough known plaintexts
            plaintext_bytes[i] = 0

    result = {
        "plaintext": bytes_to_hex(bytes(plaintext_bytes))
    }

    print(json.dumps(result))

if __name__ == "__main__":
    main()
```
